with base as (select id, order_id, status, length(status) as status_length from payments where paid_at >= to_date('2023-06-15')) select id, order_id, status, status_length, min(status_length) over (partition by status, order_id order by status_length, id rows between unbounded preceding and current row) as running_min_status_length, avg(status_length) over (partition by status, order_id order by status_length, id rows between unbounded preceding and current row) as running_avg_status_length, sum(status_length) over (partition by status, order_id order by status_length, id rows between unbounded preceding and current row) as running_sum_status_length, dense_rank() over (order by status_length) as status_length_dense_rank from base;
